fn int64ToString(num: i64): string {
  if num == 0 {
    return "0"
  }

  let result = ""
  let n = num
  let digits = "0123456789"

  while n > 0 {
    let digit = (n % 10) as i32
    result = getCharAtIndex(digits, digit) + result
    n = n / 10
  }

  return result
}

fn stringToInt64(s: string): i64 {
  let result = 0 as i64
  let i = 0

  while i < len(s) {
    let char = getCharAtIndex(s, i)

    # 문자를 숫자로 변환 ('0'=48, '1'=49, ..., '9'=57)
    if char == "0" {
      result = result * 10 + 0
    } else if char == "1" {
      result = result * 10 + 1
    } else if char == "2" {
      result = result * 10 + 2
    } else if char == "3" {
      result = result * 10 + 3
    } else if char == "4" {
      result = result * 10 + 4
    } else if char == "5" {
      result = result * 10 + 5
    } else if char == "6" {
      result = result * 10 + 6
    } else if char == "7" {
      result = result * 10 + 7
    } else if char == "8" {
      result = result * 10 + 8
    } else if char == "9" {
      result = result * 10 + 9
    } else {
      # 숫자가 아닌 문자는 무시
      break
    }

    i = i + 1
  }

  return result
}

