# ================================================================
# Part 1: Tree 엔트리 정렬
# ================================================================

# Git 정렬 규칙:
# 1. 폴더는 이름 뒤에 '/'를 붙여서 비교
# 2. 폴더가 파일보다 뒤에 옴
# 3. 이름순 정렬
fn sortTreeEntries(entries: [map]): [map] {
  # 버블 정렬 (간단하고 명확)
  let result = entries
  let n = len(result)
  let i = 0

  while i < n {
    let j = 0
    while j < (n - i - 1) {
      let current = result[j]
      let next = result[j + 1]

      # 비교: 현재와 다음의 순서가 잘못되었나?
      if shouldSwap(current, next) {
        # 스왑
        let temp = result[j]
        result[j] = result[j + 1]
        result[j + 1] = temp
      }

      j = j + 1
    }
    i = i + 1
  }

  return result
}

# 두 엔트리를 비교하여 스왑 필요 여부 판단
fn shouldSwap(entry1: map, entry2: map): bool {
  let name1 = entry1["name"]
  let name2 = entry2["name"]
  let type1 = entry1["type"]
  let type2 = entry2["type"]

  # Git 규칙: 디렉토리는 이름 뒤에 '/'를 붙여서 비교
  let sortKey1 = if type1 == "tree" then name1 + "/" else name1
  let sortKey2 = if type2 == "tree" then name2 + "/" else name2

  # 문자열 비교 (사전순)
  return compareStrings(sortKey1, sortKey2) > 0
}

# 문자열 비교
# 반환: < 0 (str1이 작음), 0 (같음), > 0 (str1이 큼)
fn compareStrings(str1: string, str2: string): i32 {
  let len1 = len(str1)
  let len2 = len(str2)
  let minLen = if len1 < len2 then len1 else len2

  let i = 0
  while i < minLen {
    let char1 = getCharCode(str1, i)
    let char2 = getCharCode(str2, i)

    if char1 != char2 {
      return char1 - char2
    }

    i = i + 1
  }

  # 모든 공통 문자가 같으면 길이로 비교
  return len1 - len2
}

# 문자의 코드값 (ASCII)
fn getCharCode(s: string, index: i32): i32 {
  # 간단한 구현 (모든 문자를 숫자로 변환)
  # 실제로는 각 문자의 ASCII 값이 필요
  if index >= len(s) {
    return 0
  }

  # 예시: 'a'=97, 'b'=98 등
  # TODO: FreeLang 문자 처리 구현
  return 0
}

# ================================================================
# Part 2: Tree 데이터 파싱
# ================================================================

# Tree 데이터 파싱 ("mode type hash\tname\n" 형식)
fn parseTreeData(data: string): [map] {
  let entries = [] as [map]
  let currentLine = ""
  let i = 0

  # 줄 단위로 파싱
  while i < len(data) {
    let char = getCharAtIndex(data, i)

    if char == "\n" {
      # 줄 끝: 파싱
      if len(currentLine) > 0 {
        let entry = parseTreeLine(currentLine)
        if entry != null {
          entries = append(entries, entry)
        }
      }
      currentLine = ""
    } else {
      # 줄에 추가
      currentLine = currentLine + char
    }

    i = i + 1
  }

  # 마지막 줄 처리
  if len(currentLine) > 0 {
    let entry = parseTreeLine(currentLine)
    if entry != null {
      entries = append(entries, entry)
    }
  }

  return entries
}

# 한 줄 파싱 ("mode type hash\tname")
fn parseTreeLine(line: string): map {
  # 탭(\t)로 분리
  let tabIndex = findChar(line, "\t")
  if tabIndex < 0 {
    return null
  }

  let leftPart = substring(line, 0, tabIndex)
  let name = substring(line, tabIndex + 1, len(line))

  # 왼쪽 부분을 공백으로 분리 ("mode type hash")
  let parts = splitBySpace(leftPart)
  if len(parts) != 3 {
    return null
  }

  let mode = parts[0]
  let objectType = parts[1]
  let hash = parts[2]

  return createTreeEntry(mode, objectType, hash, name)
}

# 공백으로 문자열 분리
fn splitBySpace(s: string): [string] {
  let result = [] as [string]
  let currentWord = ""
  let i = 0

  while i < len(s) {
    let char = getCharAtIndex(s, i)

    if char == " " {
      if len(currentWord) > 0 {
        result = append(result, currentWord)
        currentWord = ""
      }
    } else {
      currentWord = currentWord + char
    }

    i = i + 1
  }

  # 마지막 단어
  if len(currentWord) > 0 {
    result = append(result, currentWord)
  }

  return result
}

# 문자 찾기 (인덱스 반환, 없으면 -1)
