    } else {
      # 줄에 추가
      currentLine = currentLine + char
    }

    i = i + 1
  }

  # 마지막 줄 처리
  if len(currentLine) > 0 {
    let entry = parseTreeLine(currentLine)
    if entry != null {
      entries = append(entries, entry)
    }
  }

  return entries
}

# 한 줄 파싱 ("mode type hash\tname")
fn parseTreeLine(line: string): map {
  # 탭(\t)로 분리
  let tabIndex = findChar(line, "\t")
  if tabIndex < 0 {
    return null
  }

  let leftPart = substring(line, 0, tabIndex)
  let name = substring(line, tabIndex + 1, len(line))

  # 왼쪽 부분을 공백으로 분리 ("mode type hash")
  let parts = splitBySpace(leftPart)
  if len(parts) != 3 {
    return null
  }

  let mode = parts[0]
  let objectType = parts[1]
  let hash = parts[2]

  return createTreeEntry(mode, objectType, hash, name)
}

# 공백으로 문자열 분리
fn splitBySpace(s: string): [string] {
  let result = [] as [string]
  let currentWord = ""
  let i = 0

  while i < len(s) {
    let char = getCharAtIndex(s, i)

    if char == " " {
      if len(currentWord) > 0 {
        result = append(result, currentWord)
        currentWord = ""
      }
    } else {
      currentWord = currentWord + char
    }

    i = i + 1
  }

  # 마지막 단어
  if len(currentWord) > 0 {
    result = append(result, currentWord)
  }

  return result
}

# 문자 찾기 (인덱스 반환, 없으면 -1)
fn findChar(s: string, char: string): i32 {
  let i = 0
  while i < len(s) {
    if getCharAtIndex(s, i) == char {
      return i
    }
    i = i + 1
  }
  return -1
}

# 부분 문자열
fn substring(s: string, start: i32, end: i32): string {
  let result = ""
  let i = start

  while i < end && i < len(s) {
    result = result + getCharAtIndex(s, i)
    i = i + 1
  }

  return result
}

# 문자열의 인덱스 위치 문자 가져오기
fn getCharAtIndex(s: string, index: i32): string {
  # 특정 인덱스의 문자 추출
  if index < 0 || index >= len(s) {
    return ""
  }
  return substring(s, index, index + 1)
}

# ================================================================
# Part 3: Tree 엔트리 생성
# ================================================================

fn createTreeEntry(mode: string, objectType: string, hash: string, name: string): map {
  return {
    "mode": mode,
    "type": objectType,
    "hash": hash,
    "name": name
  }
}

# Tree 엔트리 직렬화
fn serializeTreeEntry(entry: map): string {
  let mode = entry["mode"]
  let entryType = entry["type"]
  let hash = entry["hash"]
  let name = entry["name"]

  return mode + " " + entryType + " " + hash + "\t" + name + "\n"
}

# ================================================================
# Part 4: Tree 해싱
# ================================================================

# 간단한 해시 함수 (테스트용)
# 실제 SHA1로는 나중에 교체
fn simpleHash(data: string): string {
  let hash = 0 as i64
  let i = 0

  # 각 문자의 ASCII 값을 곱셈-덧셈으로 해싱
  while i < len(data) {
    let charCode = getCharCode(data, i)
    hash = (hash * 31 + charCode) % 0x7FFFFFFFFFFFFFFF  # 오버플로우 방지

    i = i + 1
  }

  # 40자리 16진수로 변환
  return padToLength(toHex(hash), 40, "0")
}

# 정수를 16진수 문자열로 변환
fn toHex(num: i64): string {
  if num == 0 {
    return "0"
  }

  let hex = ""
  let hexChars = "0123456789abcdef"
  let n = num

  while n > 0 {
    let remainder = (n % 16) as i32
    hex = getCharAtHexIndex(hexChars, remainder) + hex
    n = n / 16
  }

  return hex
}

# 16진수 문자열에서 특정 인덱스 문자 추출
fn getCharAtHexIndex(hexChars: string, index: i32): string {
  # "0123456789abcdef" 에서 index 위치 문자 추출
  return getCharAtIndex(hexChars, index)
}

# 문자열을 특정 길이로 패딩
fn padToLength(s: string, length: i32, padChar: string): string {
  let currentLen = len(s)
  let result = s

  let i = 0
  while i < (length - currentLen) {
    result = padChar + result
    i = i + 1
  }

  return result
}

# ================================================================
# Part 5: Tree 생성 및 저장
# ================================================================

fn createTree(entries: [map]): map {
  # 1. 엔트리 정렬
  let sortedEntries = sortTreeEntries(entries)

  # 2. 엔트리 직렬화
  let treeData = ""
  for entry in sortedEntries {
    treeData = treeData + serializeTreeEntry(entry)
  }

  # 3. 헤더 추가
  let size = len(treeData)
  let header = "tree " + intToString(size) + "\x00"
  let fullData = header + treeData

  # 4. 해싱
  let hash = simpleHash(fullData)

  return {
    "type": "tree",
    "entries": sortedEntries,
    "data": treeData,
    "size": size,
    "hash": hash,
    "fullData": fullData
  }
}

fn storeTree(repoPath: string, tree: map): bool {
  let hash = tree["hash"]
  let fullData = tree["fullData"]

  # 저장 경로: .freegit/objects/xx/yyyyyyyy
  let dirPart = substring(hash, 0, 2)
  let filePart = substring(hash, 2, 40)
  let dirPath = repoPath + "/.freegit/objects/" + dirPart
  let filePath = dirPath + "/" + filePart

  # 디렉토리 생성
  createDirectory(dirPath)

  # 파일 저장
  writeFileContent(filePath, fullData)

  return true
}

# ================================================================
# Part 6: 유틸리티
# ================================================================

fn intToString(num: i32): string {
  if num == 0 {
    return "0"
  }

  let result = ""
  let n = num
  let digits = "0123456789"

  while n > 0 {
    let digit = n % 10
    result = getCharAtIndex(digits, digit) + result
    n = n / 10
  }

  return result
}

