# ================================================================

# Blob 생성
fn createBlob(content: string): map {
  return {
    "type": "blob",
    "content": content,
    "size": len(content),
    "hash": calculateBlobHash(content)
  }
}

# ================================================================
# Part 2: 간단한 해싱 (SHA1 대신 기본 해시)
# 실제 SHA1은 비트 연산이 복잡하므로, 먼저 간단한 버전으로 시작
# ================================================================

fn calculateBlobHash(content: string): string {
  # 형식: "blob {size}\x00{content}" 를 해싱
  let header = "blob " + toString(len(content))
  let fullData = header + "\x00" + content

  # 간단한 해시: 문자열의 각 문자 ASCII 값 합산 → 16진수
  # 실제 SHA1은 나중에 구현
  return simpleHash(fullData)
}

fn simpleHash(data: string): string {
  let hash = 0
  let i = 0

  # 간단한 해시 계산
  while i < len(data) {
    let char = charAt(data, i)
    let ascii = getAsciiValue(char)
    hash = (hash + ascii * (i + 1)) % 0xFFFFFFFF
    i = i + 1
  }

  # 16진수로 변환 (40자리)
  return padZeros(toHexString(hash), 40)
}

fn getAsciiValue(char: string): i32 {
  # ASCII 값 반환
  if char == "\x00" { return 0 }
  else if char == "\n" { return 10 }
  else if char == " " { return 32 }
  else if char == "0" { return 48 }
  else if char == "a" { return 97 }
  else if char == "b" { return 98 }
  else if char == "x" { return 120 }
  else { return 65 }  # 기본값 'A'
}

fn toHexString(num: i32): string {
  if num == 0 {
    return "0"
  }

  let hex = ""
  let hexChars = "0123456789abcdef"
  let n = num

  while n > 0 {
    let remainder = n % 16
    hex = charAt(hexChars, remainder) + hex
    n = n / 16
  }

  return hex
}

fn charAt(s: string, index: i32): string {
  # 문자열의 특정 인덱스 문자 반환
  if index < 0 || index >= len(s) {
    return ""
  }
  return substring(s, index, index + 1)
}

fn toString(num: i32): string {
  if num == 0 {
    return "0"
  }

  let result = ""
  let n = num

  while n > 0 {
    let digit = n % 10
    # ASCII: '0' = 48
    n = n / 10
  }

  return result
}

fn padZeros(s: string, length: i32): string {
  let currentLen = len(s)
  let padding = ""

  let i = 0
  while i < (length - currentLen) {
    padding = padding + "0"
    i = i + 1
  }

  return padding + s
}

