  let hash = blob["hash"]
  let content = blob["content"]

  # 저장 경로 계산: .freegit/objects/xx/yyyyyyyy
  let dirPart = substr(hash, 0, 2)
  let filePart = substr(hash, 2, 38)
  let filePath = path + "/.freegit/objects/" + dirPart + "/" + filePart

  # 파일 저장
  let objectData = "blob " + toString(blob["size"]) + "\x00" + content
  writeFile(filePath, objectData)

  return true
}

# 해시값으로 Blob 읽기
fn readBlob(path: string, hash: string): map {
  let dirPart = substr(hash, 0, 2)
  let filePart = substr(hash, 2, 38)
  let filePath = path + "/.freegit/objects/" + dirPart + "/" + filePart

  let content = readFile(filePath)

  # "blob {size}\x00{data}" 형식에서 데이터만 추출
  # TODO: 파싱 구현

  return { "type": "blob", "content": content, "hash": hash }
}

