  if !createDirectory(repoPath + "/.freegit/refs/heads") {
    return false
  }

  # 5. HEAD 파일 생성
  let headContent = "ref: refs/heads/main\n"
  if !writeFileContent(repoPath + "/.freegit/HEAD", headContent) {
    return false
  }

  return true
}

# ================================================================
