# 해시값으로 저장 경로 계산: objects/xx/yyyyyyyy
fn getObjectPath(repoPath: string, hash: string): string {
  let dirPart = substring(hash, 0, 2)
  let filePart = substring(hash, 2, len(hash))
  let objectsDir = repoPath + "/.freegit/objects"

  return objectsDir + "/" + dirPart + "/" + filePart
}

# 객체 저장 (모든 타입 공통)
fn storeObject(repoPath: string, hash: string, fullData: string): bool {
  # 1. 저장 경로 계산
  let objectPath = getObjectPath(repoPath, hash)

  # 2. 디렉토리 추출
  let dirPart = substring(hash, 0, 2)
  let objectDir = repoPath + "/.freegit/objects/" + dirPart

  # 3. 디렉토리가 없으면 생성
  if !directoryExists(objectDir) {
    if !createDirectory(objectDir) {
      return false
    }
  }

  # 4. 파일 저장
  return writeFileContent(objectPath, fullData)
}

# 객체 읽기
fn readObject(repoPath: string, hash: string): string {
  let objectPath = getObjectPath(repoPath, hash)

  if !fileExists(objectPath) {
    return ""
  }

  return readFileContent(objectPath)
}

# 객체 존재 확인 (중복 제거)
fn objectExists(repoPath: string, hash: string): bool {
  let objectPath = getObjectPath(repoPath, hash)
  return fileExists(objectPath)
}

# ================================================================
