# ================================================================

# Blob 저장 (blob.fl의 storeBlob 통합)
fn storeBlobToRepository(repoPath: string, blob: map): bool {
  let hash = blob["hash"]
  let fullData = blob["fullData"]

  return storeObject(repoPath, hash, fullData)
}

# Blob 읽기
fn readBlobFromRepository(repoPath: string, hash: string): map {
  let fullData = readObject(repoPath, hash)

  if fullData == "" {
    return {}
  }

  # "blob {size}\x00{content}" 형식 파싱
  let nullIndex = findChar(fullData, "\x00")
  if nullIndex < 0 {
    return {}
  }

  let content = substring(fullData, nullIndex + 1, len(fullData))

  return {
    "type": "blob",
    "hash": hash,
    "content": content,
    "fullData": fullData
  }
}

# ================================================================
# Part 4: Tree 저장소 관리
# ================================================================

# Tree 저장
fn storeTreeToRepository(repoPath: string, tree: map): bool {
  let hash = tree["hash"]
  let fullData = tree["fullData"]

  return storeObject(repoPath, hash, fullData)
}

# Tree 읽기
fn readTreeFromRepository(repoPath: string, hash: string): map {
  let fullData = readObject(repoPath, hash)

  if fullData == "" {
    return {}
  }

  return {
    "type": "tree",
    "hash": hash,
    "fullData": fullData
  }
}

# ================================================================
# Part 5: Commit 저장소 관리
# ================================================================

# Commit 저장
fn storeCommitToRepository(repoPath: string, commit: map): bool {
  let hash = commit["hash"]
  let fullData = commit["fullData"]

  return storeObject(repoPath, hash, fullData)
}

# Commit 읽기
fn readCommitFromRepository(repoPath: string, hash: string): map {
  let fullData = readObject(repoPath, hash)

  if fullData == "" {
    return {}
  }

  return {
    "type": "commit",
    "hash": hash,
    "fullData": fullData
