# ================================================================

fn testDeduplication(): bool {
  println("=== Test 1: Deduplication 검증 ===")

  # 테스트 데이터
  let content1 = "Hello, FreeLang!"
  let content2 = "Hello, FreeLang!"  # 동일 내용
  let content3 = "Different content"  # 다른 내용

  # Blob 1, 2 생성 (동일 내용)
  let blob1 = createBlob(content1)
  let blob2 = createBlob(content2)
  let blob3 = createBlob(content3)

  let hash1 = blob1["hash"]
  let hash2 = blob2["hash"]
  let hash3 = blob3["hash"]

  println("Blob 1 hash: " + hash1)
  println("Blob 2 hash: " + hash2)
  println("Blob 3 hash: " + hash3)

  # 검증
  let test1Passed = hash1 == hash2
  let test2Passed = hash1 != hash3

  if test1Passed && test2Passed {
    println("✅ Deduplication 검증 PASS")
    return true
  } else {
    println("❌ Deduplication 검증 FAIL")
    return false
  }
}

# ================================================================
# Test 2: Merkle Tree 검증
# 파일 수정 → 트리 해시 변경
# ================================================================

fn testMerkleTree(): bool {
  println("=== Test 2: Merkle Tree 검증 ===")

  # 1단계: 원본 파일 2개로 Tree 생성
  let file1 = createBlob("file1 content")
  let file2 = createBlob("file2 content")

  let entry1 = createTreeEntry("100644", "blob", file1["hash"], "file1.txt")
  let entry2 = createTreeEntry("100644", "blob", file2["hash"], "file2.txt")

  let entries1 = [] as [map]
  entries1 = append(entries1, entry1)
  entries1 = append(entries1, entry2)

  let tree1 = createTree(entries1)
  let treeHash1 = tree1["hash"]

  println("Original tree hash: " + treeHash1)

  # 2단계: 파일 2 내용 수정
  let file2Modified = createBlob("file2 modified content")

  let entry1Again = createTreeEntry("100644", "blob", file1["hash"], "file1.txt")
  let entry2Modified = createTreeEntry("100644", "blob", file2Modified["hash"], "file2.txt")

  let entries2 = [] as [map]
  entries2 = append(entries2, entry1Again)
  entries2 = append(entries2, entry2Modified)

  let tree2 = createTree(entries2)
  let treeHash2 = tree2["hash"]

  println("Modified tree hash: " + treeHash2)

  # 검증: 트리 해시가 달라야 함
  let test1Passed = treeHash1 != treeHash2

  if test1Passed {
    println("✅ Merkle Tree 검증 PASS")
    println("  → 파일 수정 감지: " + treeHash1 + " != " + treeHash2)
