# ================================================================
# Helper 함수들 (blob.fl, tree.fl, commit.fl과 호환)
# ================================================================

fn createBlob(content: string): map {
  let header = "blob " + intToString(len(content))
  let fullData = header + "\x00" + content

  let hash = simpleHash(fullData)

  return {
    "type": "blob",
    "content": content,
    "size": len(content),
    "hash": hash,
    "fullData": fullData
  }
}

fn createTreeEntry(mode: string, objectType: string, hash: string, name: string): map {
  return {
    "mode": mode,
    "type": objectType,
    "hash": hash,
    "name": name
  }
}

fn createTree(entries: [map]): map {
  let sortedEntries = sortTreeEntries(entries)

  let treeData = ""
  for entry in sortedEntries {
    treeData = treeData + entry["mode"] + " " + entry["type"] + " " + entry["hash"] + "\t" + entry["name"] + "\n"
  }

  let size = len(treeData)
  let header = "tree " + intToString(size)
  let fullData = header + "\x00" + treeData

  let hash = simpleHash(fullData)

  return {
    "type": "tree",
    "entries": sortedEntries,
    "data": treeData,
    "size": size,
    "hash": hash,
    "fullData": fullData
  }
}

fn createCommit(treeHash: string, parentHash: string, author: string, message: string): map {
  let timestamp = 1710610800 as i64

  let commitData = ""
  commitData = commitData + "tree " + treeHash + "\n"

  if parentHash != "" {
    commitData = commitData + "parent " + parentHash + "\n"
  }

  commitData = commitData + "author " + author + " " + int64ToString(timestamp) + "\n"
  commitData = commitData + "committer " + author + " " + int64ToString(timestamp) + "\n"
  commitData = commitData + "\n"
  commitData = commitData + message

  let header = "commit " + intToString(len(commitData))
  let fullData = header + "\x00" + commitData

  let hash = simpleHash(fullData)

  return {
    "type": "commit",
    "treeHash": treeHash,
    "parentHash": parentHash,
    "author": author,
    "timestamp": timestamp,
    "message": message,
    "hash": hash,
    "data": commitData,
    "fullData": fullData
  }
}

fn sortTreeEntries(entries: [map]): [map] {
  let result = entries
  let n = len(result)
  let i = 0

  while i < n {
    let j = 0
    while j < (n - i - 1) {
      let current = result[j]
      let next = result[j + 1]

      if shouldSwap(current, next) {
        let temp = result[j]
        result[j] = result[j + 1]
        result[j + 1] = temp
      }

      j = j + 1
    }
    i = i + 1
  }

  return result
}

fn shouldSwap(entry1: map, entry2: map): bool {
  let name1 = entry1["name"]
  let name2 = entry2["name"]
  let type1 = entry1["type"]
  let type2 = entry2["type"]

  let sortKey1 = if type1 == "tree" then name1 + "/" else name1
  let sortKey2 = if type2 == "tree" then name2 + "/" else name2

  return compareStrings(sortKey1, sortKey2) > 0
}

fn compareStrings(str1: string, str2: string): i32 {
  let len1 = len(str1)
  let len2 = len(str2)
  let minLen = if len1 < len2 then len1 else len2

  let i = 0
  while i < minLen {
    let char1 = getCharCode(str1, i)
    let char2 = getCharCode(str2, i)

    if char1 != char2 {
      return char1 - char2
    }

    i = i + 1
  }

  return len1 - len2
}

fn getCharCode(s: string, index: i32): i32 {
  if index >= len(s) {
    return 0
  }

  let char = getCharAtIndex(s, index)

  if char == " " { return 32 }
  else if char == "/" { return 47 }
  else if char == "0" { return 48 }
  else if char == "a" { return 97 }
  else { return 65 }
}

fn simpleHash(data: string): string {
  let hash = 0 as i64
  let i = 0

  while i < len(data) {
    let char = getCharAtIndex(data, i)
    let ascii = getAsciiValue(char)
    hash = (hash * 31 + ascii) % 0x7FFFFFFFFFFFFFFF

    i = i + 1
  }

  return padZeros(toHexString(hash), 40)
}

fn getAsciiValue(char: string): i64 {
  if char == "\x00" { return 0 as i64 }
  else if char == "\n" { return 10 as i64 }
  else if char == " " { return 32 as i64 }
  else if char == "0" { return 48 as i64 }
  else if char == "a" { return 97 as i64 }
  else if char == "t" { return 116 as i64 }
  else { return 65 as i64 }
}

fn toHexString(num: i64): string {
  if num == 0 {
    return "0"
  }

  let hex = ""
  let hexChars = "0123456789abcdef"
  let n = num

  while n > 0 {
    let remainder = (n % 16) as i32
    hex = getCharAtIndex(hexChars, remainder) + hex
    n = n / 16
  }

  return hex
}

fn padZeros(s: string, length: i32): string {
  let currentLen = len(s)
  let result = s

  let i = 0
  while i < (length - currentLen) {
    result = "0" + result
    i = i + 1
  }

  return result
}

fn getCharAtIndex(s: string, index: i32): string {
  if index < 0 || index >= len(s) {
    return ""
  }
  return substring(s, index, index + 1)
}

fn substring(s: string, start: i32, end: i32): string {
  let result = ""
  let i = start

  while i < end && i < len(s) {
    result = result + getCharAtIndex(s, i)
    i = i + 1
  }

  return result
}

fn findChar(s: string, char: string): i32 {
  let i = 0
  while i < len(s) {
    if getCharAtIndex(s, i) == char {
      return i
    }
    i = i + 1
  }
  return -1
}

