# ================================================================
# Phase 4-1: Network Protocol Engine
# Git Wire Protocol (pkt-line format)
# 손실 없는 메시지 전송의 기초
# ================================================================

# ================================================================
# Part 1: pkt-line 인코딩 (메시지 → 전송 형식)
# ================================================================

# pkt-line 형식: 4자리 16진수 길이 + 데이터
# 예: "hello" → "000bhello"
#     길이 5 → 0x0005 → "0005" + "hello"

fn encodePktLine(message: string): string {
  let length = len(message) + 4  # 메시지 길이 + 4자리 길이 필드 자체
  let hexLength = toHexString(length)
  let paddedLength = padToLength(hexLength, 4, "0")

  return paddedLength + message
}

# 여러 메시지를 pkt-line으로 인코딩
fn encodePktLines(messages: [string]): string {
  let result = ""

  for message in messages {
    result = result + encodePktLine(message)
  }

  return result
}

# 플러시 패킷 (메시지 구분자)
fn encodeFlushPacket(): string {
  return "0000"
}

# ================================================================
# Part 2: pkt-line 디코딩 (전송 형식 → 메시지)
# ================================================================

# pkt-line 스트림 파싱
fn decodePktLines(stream: string): [string] {
  let messages = [] as [string]
  let position = 0

  while position < len(stream) {
    # 1. 길이 필드 읽기 (4자리)
    if position + 4 > len(stream) {
      break
    }

    let lengthHex = substring(stream, position, position + 4)
    let length = parseHexToInt(lengthHex)

    # 2. 길이 0이면 플러시 패킷 (스트림 종료)
    if length == 0 {
      position = position + 4
      break
    }

    # 3. 데이터 읽기
    if position + length > len(stream) {
      break
    }

    let message = substring(stream, position + 4, position + length)
    messages = append(messages, message)

    position = position + length
  }

  return messages
}

# 단일 pkt-line 디코딩
fn decodePktLine(pktLine: string): string {
  if len(pktLine) < 4 {
    return ""
  }

  let lengthHex = substring(pktLine, 0, 4)
  let length = parseHexToInt(lengthHex)

  if length == 0 {
    return ""
  }

  return substring(pktLine, 4, length)
}

# ================================================================
# Part 3: 서비스 광고 (Capability Discovery)
# 서버의 상태를 클라이언트에게 알림
# ================================================================

# 광고 메시지 생성
fn createAdvertisement(refs: [map]): string {
  let result = ""

  # 첫 번째 ref는 null-terminated (프로토콜 규칙)
  for i in range(len(refs)) {
    let ref = refs[i]
    let hash = ref["hash"]
    let refName = ref["name"]

    let line = hash + " " + refName

    if i == 0 {
      # 첫 번째 라인: 광고 기능 추가
      line = line + "\x00agent=freelang-git/1.0"
    }

    result = result + encodePktLine(line)
  }

  # 플러시 패킷으로 끝냄
  result = result + encodeFlushPacket()

  return result
}

# 광고 메시지 파싱
fn parseAdvertisement(stream: string): map {
  let messages = decodePktLines(stream)

  let refs = [] as [map]
  let capabilities = [] as [string]

