fn encodePktLine(message: string): string {
  let length = len(message) + 4
  let hexLength = toHexString(length)
  let paddedLength = padToLength(hexLength, 4, "0")
  return paddedLength + message
}

fn encodeFlushPacket(): string {
  return "0000"
}

fn decodePktLines(stream: string): [string] {
  let messages = [] as [string]
  let position = 0

  while position < len(stream) {
    if position + 4 > len(stream) {
      break
    }

    let lengthHex = substring(stream, position, position + 4)
    let length = parseHexToInt(lengthHex)

    if length == 0 {
      position = position + 4
      break
    }

    if position + length > len(stream) {
      break
    }

    let message = substring(stream, position + 4, position + length)
    messages = append(messages, message)

    position = position + length
  }

  return messages
}

fn createAdvertisement(refs: [map]): string {
  let result = ""

  for i in range(len(refs)) {
    let ref = refs[i]
    let hash = ref["hash"]
    let refName = ref["name"]
    let line = hash + " " + refName

    if i == 0 {
      line = line + "\x00agent=freelang-git/1.0"
    }

    result = result + encodePktLine(line)
  }

  result = result + encodeFlushPacket()
  return result
}

fn parseAdvertisement(stream: string): map {
  let messages = decodePktLines(stream)
  let refs = [] as [map]
  let capabilities = [] as [string]

  for i in range(len(messages)) {
    let message = messages[i]

    if i == 0 {
      let nullIndex = findChar(message, "\x00")
      if nullIndex > 0 {
        let refPart = substring(message, 0, nullIndex)
        let capPart = substring(message, nullIndex + 1, len(message))
        let refEntry = parseRefLine(refPart)
        refs = append(refs, refEntry)
        let caps = splitBySpace(capPart)
        for cap in caps {
          capabilities = append(capabilities, cap)
        }
      } else {
        let refEntry = parseRefLine(message)
        refs = append(refs, refEntry)
      }
    } else {
      let refEntry = parseRefLine(message)
      refs = append(refs, refEntry)
    }
  }

  return {
    "refs": refs,
    "capabilities": capabilities,
    "protocol": "git"
  }
}

fn parseRefLine(line: string): map {
  let spaceIndex = findChar(line, " ")

  if spaceIndex < 0 {
    return {}
  }

  let hash = substring(line, 0, spaceIndex)
  let refName = substring(line, spaceIndex + 1, len(line))

  return {
    "hash": hash,
    "name": refName
  }
}

fn createNegotiationRequest(wantHashes: [string], haveHashes: [string]): string {
  let result = ""

  for hash in wantHashes {
    result = result + encodePktLine("want " + hash)
  }

  for hash in haveHashes {
    result = result + encodePktLine("have " + hash)
  }

  result = result + encodePktLine("done")
  result = result + encodeFlushPacket()

  return result
}

fn toHexString(num: i32): string {
  if num == 0 {
    return "0"
  }

  let hex = ""
  let hexChars = "0123456789abcdef"
  let n = num

  while n > 0 {
    let remainder = n % 16
    hex = getCharAtIndex(hexChars, remainder) + hex
    n = n / 16
  }

  return hex
}

fn parseHexToInt(hex: string): i32 {
  let result = 0
  let i = 0

  while i < len(hex) {
    let char = getCharAtIndex(hex, i)
    let digit = 0

    if char == "0" { digit = 0 }
    else if char == "1" { digit = 1 }
    else if char == "2" { digit = 2 }
    else if char == "3" { digit = 3 }
    else if char == "4" { digit = 4 }
    else if char == "5" { digit = 5 }
    else if char == "6" { digit = 6 }
    else if char == "7" { digit = 7 }
    else if char == "8" { digit = 8 }
    else if char == "9" { digit = 9 }
    else if char == "a" { digit = 10 }
    else if char == "b" { digit = 11 }
    else if char == "c" { digit = 12 }
    else if char == "d" { digit = 13 }
    else if char == "e" { digit = 14 }
    else if char == "f" { digit = 15 }

    result = result * 16 + digit
    i = i + 1
  }

  return result
}

fn padToLength(s: string, length: i32, padChar: string): string {
  let currentLen = len(s)
  let result = s

  let i = 0
  while i < (length - currentLen) {
    result = padChar + result
    i = i + 1
  }

  return result
}

fn getCharAtIndex(s: string, index: i32): string {
  if index < 0 || index >= len(s) {
    return ""
  }
  return substring(s, index, index + 1)
}

fn substring(s: string, start: i32, end: i32): string {
  let result = ""
  let i = start

  while i < end && i < len(s) {
    result = result + getCharAtIndex(s, i)
    i = i + 1
  }

  return result
}

fn findChar(s: string, char: string): i32 {
  let i = 0
  while i < len(s) {
    if getCharAtIndex(s, i) == char {
      return i
    }
    i = i + 1
  }
  return -1
}

fn splitBySpace(s: string): [string] {
  let result = [] as [string]
  let currentWord = ""
  let i = 0

  while i < len(s) {
    let char = getCharAtIndex(s, i)

    if char == " " {
      if len(currentWord) > 0 {
        result = append(result, currentWord)
        currentWord = ""
      }
    } else {
      currentWord = currentWord + char
    }

    i = i + 1
  }

  if len(currentWord) > 0 {
    result = append(result, currentWord)
  }

  return result
}

fn intToString(num: i32): string {
  if num == 0 {
    return "0"
  }

  let result = ""
  let n = num
  let digits = "0123456789"

  while n > 0 {
    let digit = n % 10
    result = getCharAtIndex(digits, digit) + result
    n = n / 10
  }

  return result
}

fn range(n: i32): [i32] {
  let result = [] as [i32]
  let i = 0

  while i < n {
    result = append(result, i)
    i = i + 1
  }

  return result
}

fn boolToString(b: bool): string {
  if b {
    return "true"
  } else {
    return "false"
  }
}

