# 슬라이딩 윈도우로 빠르게 매칭점 찾기
fn findMatchingWindows(base: string, target: string, windowSize: i32): [map] {
  let matches = [] as [map]

  let baseLen = len(base)
  let targetLen = len(target)

  if windowSize > baseLen || windowSize > targetLen {
    return matches
  }

  # Base 객체의 모든 윈도우를 해시맵 구축
  let baseWindows = [] as [map]
  let i = 0
  while i < (baseLen - windowSize + 1) {
    let window = substring(base, i, i + windowSize)
    let hash = simpleHashString(window)

    baseWindows = append(baseWindows, {
      "hash": hash,
      "offset": i,
      "window": window
    })

    i = i + 1
  }

  # Target의 모든 윈도우와 매칭
  let j = 0
  while j < (targetLen - windowSize + 1) {
    let window = substring(target, j, j + windowSize)
    let hash = simpleHashString(window)

    # Base에서 동일한 해시 찾기
    for baseWindow in baseWindows {
      if baseWindow["hash"] == hash && baseWindow["window"] == window {
        matches = append(matches, {
          "baseOffset": baseWindow["offset"],
          "targetOffset": j,
          "length": windowSize
        })
      }
    }

    j = j + 1
  }

  return matches
