# Part 3: 델타 생성 (Diff → Instructions)
# ================================================================

# 두 객체 간의 델타 계산
fn calculateDelta(baseData: string, targetData: string): [map] {
  let instructions = [] as [map]

  let baseLen = len(baseData)
  let targetLen = len(targetData)

  # 만약 완전히 다르면 전체 데이터를 ADD 명령어로 전송
  if baseLen == 0 {
    instructions = append(instructions, createDeltaInstruction(
      "ADD",
      0,
      targetLen,
      targetData
    ))
