  let matches = findMatchingWindows(baseData, targetData, windowSize)

  # 매칭을 시간순으로 정렬
  matches = sortMatches(matches)

  let targetPos = 0
  let basePos = 0

  for match in matches {
    let matchTargetOffset = match["targetOffset"]
    let matchBaseOffset = match["baseOffset"]
    let matchLength = match["length"]

    # 매칭 전까지 새로운 데이터가 있으면 ADD 명령어
    if targetPos < matchTargetOffset {
      let newData = substring(targetData, targetPos, matchTargetOffset)
      instructions = append(instructions, createDeltaInstruction(
        "ADD",
        0,
        len(newData),
        newData
      ))
    }

    # 매칭 부분은 COPY 명령어
    instructions = append(instructions, createDeltaInstruction(
      "COPY",
      matchBaseOffset,
      matchLength,
      ""
    ))

    targetPos = matchTargetOffset + matchLength
    basePos = matchBaseOffset + matchLength
  }

  # 마지막 남은 데이터 ADD
  if targetPos < targetLen {
    let newData = substring(targetData, targetPos, targetLen)
    instructions = append(instructions, createDeltaInstruction(
      "ADD",
      0,
      len(newData),
      newData
    ))
  }

  return instructions
