# 매칭점을 시간순으로 정렬 (중복 제거)
fn sortMatches(matches: [map]): [map] {
  let result = matches
  let n = len(result)
  let i = 0

  while i < n {
    let j = 0
    while j < (n - i - 1) {
      let current = result[j]
      let next = result[j + 1]

      if current["targetOffset"] > next["targetOffset"] {
        let temp = result[j]
        result[j] = result[j + 1]
        result[j + 1] = temp
      }

      j = j + 1
    }
    i = i + 1
  }

  return result
}

# ================================================================
# Part 4: 델타 적용 (Reconstruction)
# ================================================================

# 델타 명령어를 기준 데이터에 적용하여 원본 재구성
fn applyDelta(baseData: string, instructions: [map]): string {
  let result = ""

  for instruction in instructions {
    let instructionType = instruction["type"]

    if instructionType == "COPY" {
      let offset = instruction["offset"]
      let length = instruction["length"]
      result = result + substring(baseData, offset, offset + length)

    } else if instructionType == "ADD" {
      let data = instruction["data"]
      result = result + data

    } else if instructionType == "SKIP" {
