    }
  }

  return result
}

# ================================================================
# Part 5: 델타 직렬화 (바이너리 인코딩)
# ================================================================

# 델타 명령어를 바이너리 형식으로 인코딩
fn serializeDelta(instructions: [map]): string {
  let result = ""

  # 헤더: 명령어 개수
  result = result + intToString(len(instructions)) + "|"

  for instruction in instructions {
    let instructionType = instruction["type"]
    let offset = instruction["offset"]
    let length = instruction["length"]
    let data = instruction["data"]

    # 형식: TYPE:offset:length:data|
    result = result + instructionType + ":"
    result = result + intToString(offset) + ":"
    result = result + intToString(length) + ":"

    if instructionType == "ADD" {
      result = result + data
    }

    result = result + "|"
  }

  return result
}

# 바이너리 델타를 명령어로 역직렬화
fn deserializeDelta(serialized: string): [map] {
  let instructions = [] as [map]

  # 파이프로 구분된 명령어 파싱
  let parts = splitByDelimiter(serialized, "|")

  let i = 1  # 첫 번째는 개수
  while i < len(parts) {
    let part = parts[i]

    if len(part) == 0 {
      break
    }

    # 콜론으로 구분
    let fields = splitByDelimiter(part, ":")

    if len(fields) >= 3 {
      let instructionType = fields[0]
      let offset = parseStringToInt(fields[1])
      let length = parseStringToInt(fields[2])
      let data = ""

      if instructionType == "ADD" && len(fields) >= 4 {
        data = fields[3]
      }

      instructions = append(instructions, createDeltaInstruction(
        instructionType,
        offset,
        length,
        data
      ))
    }

    i = i + 1
  }

  return instructions
}

# ================================================================
# Part 6: 압축률 계산
# ================================================================

# 델타의 압축 효율 측정
fn calculateCompressionRatio(originalSize: i32, deltaSize: i32): f64 {
  if originalSize == 0 {
    return 0.0
  }

  let ratio = (deltaSize as f64) / (originalSize as f64)
  return ratio
}

# 델타 크기 추정
fn estimateDeltaSize(instructions: [map]): i32 {
  let size = 0

  for instruction in instructions {
    let instructionType = instruction["type"]
    let length = instruction["length"]
    let data = instruction["data"]

    # 오버헤드: TYPE + offset + length (대략 30바이트)
    size = size + 30

    if instructionType == "ADD" {
      size = size + len(data)
    }
  }

  return size
}

# ================================================================
# Part 7: 유틸리티 함수
# ================================================================

fn simpleHashString(s: string): string {
  let hash = 0 as i64
  let i = 0

  while i < len(s) {
    let char = getCharAtIndex(s, i)
    let ascii = getAsciiValue(char)
    hash = (hash * 31 + ascii) % 0x7FFFFFFFFFFFFFFF
    i = i + 1
  }

  return int64ToHex(hash)
}

fn int64ToHex(num: i64): string {
  if num == 0 {
    return "0"
  }

  let hex = ""
  let hexChars = "0123456789abcdef"
  let n = num

  while n > 0 {
    let remainder = (n % 16) as i32
    hex = getCharAtIndex(hexChars, remainder) + hex
    n = n / 16
  }

  return hex
}

fn getCharAtIndex(s: string, index: i32): string {
  if index < 0 || index >= len(s) {
    return ""
  }
  return substring(s, index, index + 1)
}

fn substring(s: string, start: i32, end: i32): string {
  let result = ""
  let i = start

  while i < end && i < len(s) {
    result = result + getCharAtIndex(s, i)
    i = i + 1
  }

  return result
}

fn intToString(num: i32): string {
  if num == 0 {
    return "0"
  }

  let result = ""
  let n = num
  let digits = "0123456789"

  while n > 0 {
    let digit = n % 10
    result = getCharAtIndex(digits, digit) + result
    n = n / 10
  }

  return result
}

fn parseStringToInt(s: string): i32 {
  let result = 0
  let i = 0

  while i < len(s) {
    let char = getCharAtIndex(s, i)

    if char == "0" { result = result * 10 + 0 }
    else if char == "1" { result = result * 10 + 1 }
    else if char == "2" { result = result * 10 + 2 }
    else if char == "3" { result = result * 10 + 3 }
    else if char == "4" { result = result * 10 + 4 }
    else if char == "5" { result = result * 10 + 5 }
    else if char == "6" { result = result * 10 + 6 }
    else if char == "7" { result = result * 10 + 7 }
    else if char == "8" { result = result * 10 + 8 }
    else if char == "9" { result = result * 10 + 9 }

    i = i + 1
  }

  return result
}

fn getAsciiValue(char: string): i64 {
  if char == "\x00" { return 0 as i64 }
  else if char == " " { return 32 as i64 }
  else if char == "0" { return 48 as i64 }
  else if char == "a" { return 97 as i64 }
  else { return 65 as i64 }
}

fn splitByDelimiter(s: string, delim: string): [string] {
  let result = [] as [string]
  let current = ""
  let i = 0

  while i < len(s) {
    let char = getCharAtIndex(s, i)

    if char == delim {
      result = append(result, current)
      current = ""
    } else {
      current = current + char
    }

    i = i + 1
  }

  result = append(result, current)
  return result
}

