# 델타 명령어를 바이너리 형식으로 인코딩
fn serializeDelta(instructions: [map]): string {
  let result = ""

  # 헤더: 명령어 개수
  result = result + intToString(len(instructions)) + "|"

  for instruction in instructions {
    let instructionType = instruction["type"]
    let offset = instruction["offset"]
    let length = instruction["length"]
    let data = instruction["data"]

    # 형식: TYPE:offset:length:data|
    result = result + instructionType + ":"
    result = result + intToString(offset) + ":"
    result = result + intToString(length) + ":"

    if instructionType == "ADD" {
      result = result + data
    }

    result = result + "|"
  }

  return result
}

# 바이너리 델타를 명령어로 역직렬화
fn deserializeDelta(serialized: string): [map] {
  let instructions = [] as [map]

  # 파이프로 구분된 명령어 파싱
  let parts = splitByDelimiter(serialized, "|")

  let i = 1  # 첫 번째는 개수
  while i < len(parts) {
    let part = parts[i]

    if len(part) == 0 {
      break
    }

    # 콜론으로 구분
    let fields = splitByDelimiter(part, ":")

    if len(fields) >= 3 {
      let instructionType = fields[0]
      let offset = parseStringToInt(fields[1])
      let length = parseStringToInt(fields[2])
      let data = ""

      if instructionType == "ADD" && len(fields) >= 4 {
