fn findLongestCommonSubstring(base: string, target: string): map {
  let maxLength = 0
  let bestBaseOffset = 0
  let bestTargetOffset = 0

  let baseLen = len(base)
  let targetLen = len(target)

  let i = 0
  while i < baseLen {
    let j = 0
    while j < targetLen {
      let matchLength = 0
      let k = 0

      while i + k < baseLen && j + k < targetLen {
        if substring(base, i + k, i + k + 1) == substring(target, j + k, j + k + 1) {
          matchLength = matchLength + 1
          k = k + 1
        } else {
          break
        }
      }

      if matchLength > maxLength {
        maxLength = matchLength
        bestBaseOffset = i
        bestTargetOffset = j
      }

      j = j + 1
    }
    i = i + 1
  }

  return {
    "baseOffset": bestBaseOffset,
    "targetOffset": bestTargetOffset,
    "length": maxLength
  }
}

fn findMatchingWindows(base: string, target: string, windowSize: i32): [map] {
  let matches = [] as [map]

  let baseLen = len(base)
  let targetLen = len(target)

  if windowSize > baseLen || windowSize > targetLen {
    return matches
  }

  let baseWindows = [] as [map]
  let i = 0
  while i < (baseLen - windowSize + 1) {
    let window = substring(base, i, i + windowSize)
    let hash = simpleHashString(window)

    baseWindows = append(baseWindows, {
      "hash": hash,
      "offset": i,
      "window": window
    })

    i = i + 1
  }

  let j = 0
  while j < (targetLen - windowSize + 1) {
    let window = substring(target, j, j + windowSize)
    let hash = simpleHashString(window)

    for baseWindow in baseWindows {
      if baseWindow["hash"] == hash && baseWindow["window"] == window {
        matches = append(matches, {
          "baseOffset": baseWindow["offset"],
          "targetOffset": j,
          "length": windowSize
        })
      }
    }

    j = j + 1
  }

  return matches
}

fn calculateDelta(baseData: string, targetData: string): [map] {
  let instructions = [] as [map]

  let baseLen = len(baseData)
  let targetLen = len(targetData)

  if baseLen == 0 {
    instructions = append(instructions, {
      "type": "ADD",
      "offset": 0,
      "length": targetLen,
      "data": targetData
    })
    return instructions
  }

  let windowSize = if baseLen < 256 then 16 else 32
  let matches = findMatchingWindows(baseData, targetData, windowSize)

  matches = sortMatches(matches)

  let targetPos = 0
  let basePos = 0

  for match in matches {
    let matchTargetOffset = match["targetOffset"]
    let matchBaseOffset = match["baseOffset"]
    let matchLength = match["length"]

    if targetPos < matchTargetOffset {
      let newData = substring(targetData, targetPos, matchTargetOffset)
      instructions = append(instructions, {
        "type": "ADD",
        "offset": 0,
        "length": len(newData),
        "data": newData
      })
    }

    instructions = append(instructions, {
      "type": "COPY",
      "offset": matchBaseOffset,
      "length": matchLength,
      "data": ""
    })

    targetPos = matchTargetOffset + matchLength
    basePos = matchBaseOffset + matchLength
  }

  if targetPos < targetLen {
    let newData = substring(targetData, targetPos, targetLen)
    instructions = append(instructions, {
      "type": "ADD",
      "offset": 0,
      "length": len(newData),
      "data": newData
    })
  }

