# ================================================================
# Helper 함수들 (delta.fl에서 복사)
# ================================================================

fn findLongestCommonSubstring(base: string, target: string): map {
  let maxLength = 0
  let bestBaseOffset = 0
  let bestTargetOffset = 0

  let baseLen = len(base)
  let targetLen = len(target)

  let i = 0
  while i < baseLen {
    let j = 0
    while j < targetLen {
      let matchLength = 0
      let k = 0

      while i + k < baseLen && j + k < targetLen {
        if substring(base, i + k, i + k + 1) == substring(target, j + k, j + k + 1) {
          matchLength = matchLength + 1
          k = k + 1
        } else {
          break
        }
      }

      if matchLength > maxLength {
        maxLength = matchLength
        bestBaseOffset = i
        bestTargetOffset = j
      }

      j = j + 1
    }
    i = i + 1
  }

  return {
    "baseOffset": bestBaseOffset,
    "targetOffset": bestTargetOffset,
    "length": maxLength
  }
}

fn findMatchingWindows(base: string, target: string, windowSize: i32): [map] {
  let matches = [] as [map]

  let baseLen = len(base)
  let targetLen = len(target)

  if windowSize > baseLen || windowSize > targetLen {
    return matches
  }

  let baseWindows = [] as [map]
  let i = 0
  while i < (baseLen - windowSize + 1) {
    let window = substring(base, i, i + windowSize)
    let hash = simpleHashString(window)

    baseWindows = append(baseWindows, {
      "hash": hash,
      "offset": i,
      "window": window
    })

    i = i + 1
  }

  let j = 0
  while j < (targetLen - windowSize + 1) {
    let window = substring(target, j, j + windowSize)
    let hash = simpleHashString(window)

    for baseWindow in baseWindows {
      if baseWindow["hash"] == hash && baseWindow["window"] == window {
        matches = append(matches, {
          "baseOffset": baseWindow["offset"],
          "targetOffset": j,
          "length": windowSize
        })
      }
    }

    j = j + 1
  }

  return matches
}

fn calculateDelta(baseData: string, targetData: string): [map] {
  let instructions = [] as [map]

  let baseLen = len(baseData)
  let targetLen = len(targetData)

  if baseLen == 0 {
    instructions = append(instructions, {
      "type": "ADD",
      "offset": 0,
      "length": targetLen,
      "data": targetData
    })
    return instructions
  }

  let windowSize = if baseLen < 256 then 16 else 32
  let matches = findMatchingWindows(baseData, targetData, windowSize)

  matches = sortMatches(matches)

  let targetPos = 0
  let basePos = 0

  for match in matches {
    let matchTargetOffset = match["targetOffset"]
    let matchBaseOffset = match["baseOffset"]
    let matchLength = match["length"]

    if targetPos < matchTargetOffset {
      let newData = substring(targetData, targetPos, matchTargetOffset)
      instructions = append(instructions, {
        "type": "ADD",
        "offset": 0,
        "length": len(newData),
        "data": newData
      })
    }

    instructions = append(instructions, {
      "type": "COPY",
      "offset": matchBaseOffset,
      "length": matchLength,
      "data": ""
    })

    targetPos = matchTargetOffset + matchLength
    basePos = matchBaseOffset + matchLength
  }

  if targetPos < targetLen {
    let newData = substring(targetData, targetPos, targetLen)
    instructions = append(instructions, {
      "type": "ADD",
      "offset": 0,
      "length": len(newData),
      "data": newData
    })
  }

  return instructions
}

fn sortMatches(matches: [map]): [map] {
  let result = matches
  let n = len(result)
  let i = 0

  while i < n {
    let j = 0
    while j < (n - i - 1) {
      let current = result[j]
      let next = result[j + 1]

      if current["targetOffset"] > next["targetOffset"] {
        let temp = result[j]
        result[j] = result[j + 1]
        result[j + 1] = temp
      }

      j = j + 1
    }
    i = i + 1
  }

  return result
}

fn applyDelta(baseData: string, instructions: [map]): string {
  let result = ""

  for instruction in instructions {
    let instructionType = instruction["type"]

    if instructionType == "COPY" {
      let offset = instruction["offset"]
      let length = instruction["length"]
      result = result + substring(baseData, offset, offset + length)

    } else if instructionType == "ADD" {
      let data = instruction["data"]
      result = result + data
    }
  }

  return result
}

fn serializeDelta(instructions: [map]): string {
  let result = ""

  result = result + intToString(len(instructions)) + "|"

  for instruction in instructions {
    let instructionType = instruction["type"]
    let offset = instruction["offset"]
    let length = instruction["length"]
    let data = instruction["data"]

    result = result + instructionType + ":"
    result = result + intToString(offset) + ":"
    result = result + intToString(length) + ":"

    if instructionType == "ADD" {
      result = result + data
    }

    result = result + "|"
  }

  return result
}

fn deserializeDelta(serialized: string): [map] {
  let instructions = [] as [map]

  let parts = splitByDelimiter(serialized, "|")

  let i = 1
  while i < len(parts) {
    let part = parts[i]

    if len(part) == 0 {
      break
    }

    let fields = splitByDelimiter(part, ":")

    if len(fields) >= 3 {
      let instructionType = fields[0]
      let offset = parseStringToInt(fields[1])
      let length = parseStringToInt(fields[2])
      let data = ""

      if instructionType == "ADD" && len(fields) >= 4 {
        data = fields[3]
      }

      instructions = append(instructions, {
        "type": instructionType,
        "offset": offset,
        "length": length,
        "data": data
      })
    }

    i = i + 1
  }

  return instructions
}

fn estimateDeltaSize(instructions: [map]): i32 {
  let size = 0

  for instruction in instructions {
    let instructionType = instruction["type"]
    let length = instruction["length"]
    let data = instruction["data"]

    size = size + 30

    if instructionType == "ADD" {
      size = size + len(data)
    }
  }

  return size
}

fn calculateCompressionRatio(originalSize: i32, deltaSize: i32): f64 {
  if originalSize == 0 {
    return 0.0
  }

  return (deltaSize as f64) / (originalSize as f64)
}

fn simpleHashString(s: string): string {
  let hash = 0 as i64
  let i = 0

  while i < len(s) {
    let char = getCharAtIndex(s, i)
    let ascii = getAsciiValue(char)
    hash = (hash * 31 + ascii) % 0x7FFFFFFFFFFFFFFF
    i = i + 1
  }

  return int64ToHex(hash)
}

fn int64ToHex(num: i64): string {
  if num == 0 {
    return "0"
  }

  let hex = ""
  let hexChars = "0123456789abcdef"
  let n = num

  while n > 0 {
    let remainder = (n % 16) as i32
    hex = getCharAtIndex(hexChars, remainder) + hex
    n = n / 16
  }

  return hex
}

fn getCharAtIndex(s: string, index: i32): string {
  if index < 0 || index >= len(s) {
    return ""
  }
  return substring(s, index, index + 1)
}

fn substring(s: string, start: i32, end: i32): string {
  let result = ""
  let i = start

  while i < end && i < len(s) {
    result = result + getCharAtIndex(s, i)
    i = i + 1
  }

  return result
}

fn intToString(num: i32): string {
  if num == 0 {
    return "0"
  }

  let result = ""
  let n = num
  let digits = "0123456789"

  while n > 0 {
    let digit = n % 10
    result = getCharAtIndex(digits, digit) + result
    n = n / 10
  }

  return result
}

fn parseStringToInt(s: string): i32 {
  let result = 0
  let i = 0

  while i < len(s) {
    let char = getCharAtIndex(s, i)

    if char == "0" { result = result * 10 + 0 }
    else if char == "1" { result = result * 10 + 1 }
    else if char == "2" { result = result * 10 + 2 }
    else if char == "3" { result = result * 10 + 3 }
    else if char == "4" { result = result * 10 + 4 }
    else if char == "5" { result = result * 10 + 5 }
    else if char == "6" { result = result * 10 + 6 }
    else if char == "7" { result = result * 10 + 7 }
    else if char == "8" { result = result * 10 + 8 }
    else if char == "9" { result = result * 10 + 9 }

    i = i + 1
  }

  return result
}

fn getAsciiValue(char: string): i64 {
  if char == "\x00" { return 0 as i64 }
  else if char == " " { return 32 as i64 }
  else if char == "0" { return 48 as i64 }
  else if char == "a" { return 97 as i64 }
  else { return 65 as i64 }
}

fn splitByDelimiter(s: string, delim: string): [string] {
  let result = [] as [string]
  let current = ""
  let i = 0

  while i < len(s) {
    let char = getCharAtIndex(s, i)

    if char == delim {
      result = append(result, current)
      current = ""
    } else {
      current = current + char
    }

    i = i + 1
  }

  result = append(result, current)
  return result
}

fn range(n: i32): [i32] {
  let result = [] as [i32]
  let i = 0

  while i < n {
    result = append(result, i)
    i = i + 1
  }

  return result
}

fn floatToString(f: f64): string {
  let intPart = f as i32
  let result = intToString(intPart) + "."

  let decPart = ((f - (intPart as f64)) * 100.0) as i32
  result = result + intToString(decPart)

  return result
}

