fn createPushRequest(localCommits: [map], localRefs: [map]): string {
  let stream = ""

  for ref in localRefs {
    let refName = ref["name"]
    let commitHash = ref["hash"]
    stream = stream + encodePktLine("push " + refName + " " + commitHash)
  }

  stream = stream + encodeFlushPacket()

  for commit in localCommits {
    let hash = commit["hash"]
    let fullData = commit["fullData"]
    stream = stream + encodePktLine("object " + hash)
    stream = stream + encodePktLine(fullData)
  }

  stream = stream + encodeFlushPacket()

  return stream
}

fn createPullRequest(localRefs: [map]): string {
  let stream = ""

  for ref in localRefs {
    let commitHash = ref["hash"]
    stream = stream + encodePktLine("want " + commitHash)
  }

  stream = stream + encodePktLine("done")
  stream = stream + encodeFlushPacket()

  return stream
}

fn createPullResponse(remote: map, pullRequest: string): string {
  let response = ""

  response = response + encodePktLine("ACK")
  response = response + encodePktLine("packfile-start")

  for remoteObj in remote["objects"] {
    let hash = remoteObj["hash"]
    let data = remoteObj["data"]
    response = response + encodePktLine("object " + hash)
    response = response + encodePktLine(data)
  }

  response = response + encodeFlushPacket()

  return response
}

fn initializeRemoteRepository(): map {
  return {
    "refs": [] as [map],
    "objects": [] as [map],
    "totalSize": 0
  }
}

fn storeRemoteObject(remote: map, objectHash: string, objectData: string): map {
  let objects = remote["objects"]

  objects = append(objects, {
    "hash": objectHash,
    "data": objectData,
    "size": len(objectData)
  })

  remote["objects"] = objects
  remote["totalSize"] = remote["totalSize"] + len(objectData)

  return remote
}

fn updateRemoteRef(remote: map, refName: string, commitHash: string): map {
  let refs = remote["refs"]

  let found = false
  let i = 0

  while i < len(refs) {
    if refs[i]["name"] == refName {
      refs[i]["hash"] = commitHash
      found = true
      break
    }
    i = i + 1
  }

  if !found {
    refs = append(refs, {
      "name": refName,
      "hash": commitHash
    })
  }

  remote["refs"] = refs
  return remote
}

fn handlePushRequest(remote: map, pushStream: string): map {
  let messages = decodePktLines(pushStream)

  let refUpdates = [] as [map]
  let objects = [] as [map]
  let readingObjects = false

  for message in messages {
    if substring(message, 0, 4) == "push" {
      let parts = splitBySpace(message)
      if len(parts) >= 3 {
        let refName = parts[1]
        let commitHash = parts[2]
        refUpdates = append(refUpdates, {
          "name": refName,
          "hash": commitHash
        })
      }
    } else if substring(message, 0, 6) == "object" {
      readingObjects = true
    } else if readingObjects {
      objects = append(objects, message)
    }
  }

  for refUpdate in refUpdates {
    remote = updateRemoteRef(remote, refUpdate["name"], refUpdate["hash"])
  }

  for i in range(len(objects)) {
    let objectData = objects[i]
    remote = storeRemoteObject(remote, intToString(i), objectData)
  }

  return remote
}

fn calculateSyncStats(local: map, remote: map): map {
  let localObjectCount = len(local["objects"])
  let remoteObjectCount = len(remote["objects"])

  let divergence = if localObjectCount > remoteObjectCount then
    localObjectCount - remoteObjectCount
  else
    0

  return {
    "localObjects": localObjectCount,
    "remoteObjects": remoteObjectCount,
    "divergence": divergence,
    "compression": "delta-enabled"
  }
}

fn estimateTransferSize(objects: [map], useDelta: bool): i32 {
  let totalSize = 0

  for obj in objects {
    let data = obj["data"]
    let baseSize = len(data)

    if useDelta {
      totalSize = totalSize + (baseSize / 2)
    } else {
      totalSize = totalSize + baseSize
    }

    totalSize = totalSize + 30
  }

  return totalSize
}

fn simulateNetworkTransfer(transferSize: i32, bandwidthMbps: i32): i32 {
  if bandwidthMbps == 0 {
    return 0
  }

  let bandwidthBytesPerSec = bandwidthMbps * 1000000 / 8
  let transferTimeSeconds = transferSize / bandwidthBytesPerSec

  if transferTimeSeconds == 0 {
    transferTimeSeconds = 1
  }

  return transferTimeSeconds
}

fn encodePktLine(message: string): string {
  let length = len(message) + 4
  let hexLength = toHexString(length)
  let paddedLength = padToLength(hexLength, 4, "0")
  return paddedLength + message
}

fn encodeFlushPacket(): string {
  return "0000"
}

fn decodePktLines(stream: string): [string] {
  let messages = [] as [string]
  let position = 0

  while position < len(stream) {
    if position + 4 > len(stream) {
      break
    }

    let lengthHex = substring(stream, position, position + 4)
    let length = parseHexToInt(lengthHex)

    if length == 0 {
      position = position + 4
      break
    }

    if position + length > len(stream) {
      break
    }

    let message = substring(stream, position + 4, position + length)
    messages = append(messages, message)

    position = position + length
  }

  return messages
}

fn toHexString(num: i32): string {
  if num == 0 {
    return "0"
  }

  let hex = ""
  let hexChars = "0123456789abcdef"
  let n = num

  while n > 0 {
    let remainder = n % 16
    hex = getCharAtIndex(hexChars, remainder) + hex
    n = n / 16
  }

  return hex
}

fn parseHexToInt(hex: string): i32 {
  let result = 0
  let i = 0

  while i < len(hex) {
    let char = getCharAtIndex(hex, i)
    let digit = 0

    if char == "0" { digit = 0 }
    else if char == "1" { digit = 1 }
    else if char == "2" { digit = 2 }
    else if char == "3" { digit = 3 }
    else if char == "4" { digit = 4 }
    else if char == "5" { digit = 5 }
    else if char == "6" { digit = 6 }
    else if char == "7" { digit = 7 }
    else if char == "8" { digit = 8 }
    else if char == "9" { digit = 9 }
    else if char == "a" { digit = 10 }
    else if char == "b" { digit = 11 }
    else if char == "c" { digit = 12 }
    else if char == "d" { digit = 13 }
    else if char == "e" { digit = 14 }
    else if char == "f" { digit = 15 }

    result = result * 16 + digit
    i = i + 1
  }

  return result
}

fn padToLength(s: string, length: i32, padChar: string): string {
  let currentLen = len(s)
  let result = s

  let i = 0
  while i < (length - currentLen) {
    result = padChar + result
    i = i + 1
  }

  return result
}

fn getCharAtIndex(s: string, index: i32): string {
  if index < 0 || index >= len(s) {
    return ""
  }
  return substring(s, index, index + 1)
}

fn substring(s: string, start: i32, end: i32): string {
  let result = ""
  let i = start

  while i < end && i < len(s) {
    result = result + getCharAtIndex(s, i)
    i = i + 1
  }

  return result
}

fn splitBySpace(s: string): [string] {
  let result = [] as [string]
  let currentWord = ""
  let i = 0

  while i < len(s) {
    let char = getCharAtIndex(s, i)

    if char == " " {
      if len(currentWord) > 0 {
        result = append(result, currentWord)
        currentWord = ""
      }
    } else {
      currentWord = currentWord + char
    }

    i = i + 1
  }

  if len(currentWord) > 0 {
    result = append(result, currentWord)
  }

  return result
}

fn intToString(num: i32): string {
  if num == 0 {
    return "0"
  }

  let result = ""
  let n = num
  let digits = "0123456789"

  while n > 0 {
    let digit = n % 10
    result = getCharAtIndex(digits, digit) + result
    n = n / 10
  }

  return result
}

fn floatToString(f: f64): string {
  let intPart = f as i32
  let result = intToString(intPart) + "."

  let decPart = ((f - (intPart as f64)) * 100.0) as i32
  result = result + intToString(decPart)

  return result
}

fn range(n: i32): [i32] {
  let result = [] as [i32]
  let i = 0

  while i < n {
    result = append(result, i)
    i = i + 1
  }

  return result
}

