# 메시지 서명 검증
fn verifyMessageSignature(message: map, signingKey: string): bool {
  let signature = message["signature"]
  let dataToSign = message["id"] + message["from"] + message["action"] + intToString(message["timestamp"] as i32)
  let expectedSignature = simpleSignature(dataToSign, signingKey)

  return signature == expectedSignature
}

# 간단한 서명 함수 (HMAC 대신)
fn simpleSignature(data: string, key: string): string {
  let hash = 0 as i64
  let i = 0

  while i < len(data) {
    let char = getCharAtIndex(data, i)
    let keyChar = getCharAtIndex(key, i % len(key))
    hash = (hash * 31 + getAsciiValue(char) + getAsciiValue(keyChar)) % 0x7FFFFFFFFFFFFFFF
    i = i + 1
  }

  return padToLength(toHexString(hash as i32), 40, "0")
}

