# ================================================================
# AI-Polyglot: Agent-to-Agent Protocol Engine
# 5명 AI 에이전트의 규격화된 메시지 통신 시스템
# ================================================================

# ================================================================
# Part 1: 메시지 정의
# ================================================================

# 에이전트 ID 정의
fn getAgentId(agentName: string): string {
  if agentName == "cmo" { return "agent:cmo:opus" }
  else if agentName == "content-writer" { return "agent:content-writer:sonnet" }
  else if agentName == "social-media" { return "agent:social-media:haiku" }
  else if agentName == "community-manager" { return "agent:community-manager:haiku" }
  else if agentName == "analytics" { return "agent:analytics:haiku" }
  else { return "agent:unknown" }
}

# 메시지 생성
fn createMessage(
  fromAgent: string,
  toAgent: string,
  messageType: string,
  action: string,
  payload: map
): map {
  let timestamp = getCurrentTimestamp()
  let messageId = generateMessageId()

  return {
    "id": messageId,
    "from": getAgentId(fromAgent),
    "to": if toAgent == "broadcast" then "broadcast" else getAgentId(toAgent),
    "type": messageType,
    "action": action,
    "payload": payload,
    "timestamp": timestamp,
    "status": "pending",
    "retries": 0,
    "signature": ""
  }
}

# Request 메시지 (에이전트가 다른 에이전트에게 작업 요청)
fn createRequestMessage(
  from: string,
  to: string,
  action: string,
  payload: map
): map {
  return createMessage(from, to, "request", action, payload)
}

# Response 메시지 (요청에 대한 응답)
fn createResponseMessage(
  from: string,
  to: string,
  action: string,
  status: string,
  result: map
): map {
  let payload = {
    "action": action,
    "status": status,
    "result": result
  }

  return createMessage(from, to, "response", action, payload)
}

# Event 메시지 (상태 변화 알림)
fn createEventMessage(
  from: string,
  eventType: string,
  eventData: map
): map {
  let payload = {
    "eventType": eventType,
    "data": eventData
  }

  return createMessage(from, "broadcast", "event", eventType, payload)
}

# ================================================================
# Part 2: 메시지 직렬화/역직렬화
# ================================================================

# 메시지를 문자열로 직렬화 (JSON 형식)
fn serializeMessage(message: map): string {
  let result = "{"

  result = result + "\"id\":\"" + message["id"] + "\","
  result = result + "\"from\":\"" + message["from"] + "\","
  result = result + "\"to\":\"" + message["to"] + "\","
  result = result + "\"type\":\"" + message["type"] + "\","
  result = result + "\"action\":\"" + message["action"] + "\","
  result = result + "\"timestamp\":" + int64ToString(message["timestamp"]) + ","
  result = result + "\"status\":\"" + message["status"] + "\""

  result = result + "}"

  return result
}

# 직렬화된 메시지를 파싱
fn deserializeMessage(jsonStr: string): map {
  # 간단한 파싱 (실제로는 JSON 파서 필요)
  let message = {
    "id": "",
    "from": "",
    "to": "",
    "type": "",
    "action": "",
    "timestamp": 0 as i64,
    "status": ""
  }

  return message
}

# ================================================================
# Part 3: 메시지 라우팅
# ================================================================

# 메시지 큐 생성
fn createMessageQueue(): map {
  return {
    "messages": [] as [map],
    "processed": 0,
    "failed": 0
  }
}

# 메시지를 큐에 추가
fn enqueueMessage(queue: map, message: map): map {
  let messages = queue["messages"]
  messages = append(messages, message)
  queue["messages"] = messages

  return queue
}

# 큐에서 메시지 꺼내기 (FIFO)
fn dequeueMessage(queue: map): map {
  if len(queue["messages"]) == 0 {
    return {}
  }

  let messages = queue["messages"]
  let message = messages[0]

  # 첫 번째 메시지 제거
  let newMessages = [] as [map]
  let i = 1
  while i < len(messages) {
    newMessages = append(newMessages, messages[i])
    i = i + 1
  }

  queue["messages"] = newMessages

  return message
}

# 특정 에이전트에게 보낸 메시지 필터링
fn filterMessagesForAgent(queue: map, agentId: string): [map] {
  let result = [] as [map]

  for message in queue["messages"] {
    let to = message["to"]

    if to == agentId || to == "broadcast" {
      result = append(result, message)
    }
  }

  return result
}

# 메시지 처리 상태 업데이트
