  let queue = createMessageQueue()

  # 여러 메시지 추가
  let msg1 = createRequestMessage("cmo", "analytics", "analyze_metrics", {})
  let msg2 = createRequestMessage("content-writer", "cmo", "report_progress", {})
  let msg3 = createEventMessage("analytics", "metrics_ready", {})

  queue = enqueueMessage(queue, msg1)
  queue = enqueueMessage(queue, msg2)
  queue = enqueueMessage(queue, msg3)

  # Analytics에게 보낸 메시지 필터
  let analyticsAgentId = getAgentId("analytics")
  let analyticsMessages = filterMessagesForAgent(queue, analyticsAgentId)

  println("Total messages: " + intToString(len(queue["messages"])))
  println("Messages for analytics: " + intToString(len(analyticsMessages)))

  let test1 = len(analyticsMessages) >= 1

  if test1 {
    println("✅ 에이전트 필터링 PASS")
    return true
  } else {
    println("❌ 에이전트 필터링 FAIL")
    return false
  }
}

