fn createRequestMessage(from: string, to: string, action: string, payload: map): map {
  let timestamp = 1710610800 as i64
  let messageId = "msg:" + intToString(1) + ":1"

  return {
    "id": messageId,
    "from": getAgentId(from),
    "to": getAgentId(to),
    "type": "request",
    "action": action,
    "payload": payload,
    "timestamp": timestamp,
    "status": "pending",
    "retries": 0,
    "signature": ""
  }
}

fn createResponseMessage(from: string, to: string, action: string, status: string, result: map): map {
  let timestamp = 1710610800 as i64
  let messageId = "msg:" + intToString(2) + ":1"

  let payload = {
    "action": action,
    "status": status,
    "result": result
  }

  return {
    "id": messageId,
    "from": getAgentId(from),
    "to": getAgentId(to),
    "type": "response",
    "action": action,
    "payload": payload,
    "timestamp": timestamp,
    "status": "completed",
    "signature": ""
  }
}

fn createEventMessage(from: string, eventType: string, eventData: map): map {
  let timestamp = 1710610800 as i64
  let messageId = "msg:" + intToString(3) + ":1"

  let payload = {
    "eventType": eventType,
    "data": eventData
  }

  return {
    "id": messageId,
    "from": getAgentId(from),
    "to": "broadcast",
    "type": "event",
    "action": eventType,
    "payload": payload,
    "timestamp": timestamp,
    "status": "sent",
    "signature": ""
  }
}

fn createMessageQueue(): map {
  return {
    "messages": [] as [map],
    "processed": 0,
    "failed": 0
  }
}

fn enqueueMessage(queue: map, message: map): map {
  let messages = queue["messages"]
  messages = append(messages, message)
  queue["messages"] = messages
  return queue
}

fn dequeueMessage(queue: map): map {
  if len(queue["messages"]) == 0 {
    return {}
  }

  let messages = queue["messages"]
  let message = messages[0]

  let newMessages = [] as [map]
  let i = 1
  while i < len(messages) {
    newMessages = append(newMessages, messages[i])
    i = i + 1
  }

  queue["messages"] = newMessages
  return message
}

fn filterMessagesForAgent(queue: map, agentId: string): [map] {
  let result = [] as [map]

  for message in queue["messages"] {
    let to = message["to"]

    if to == agentId || to == "broadcast" {
      result = append(result, message)
    }
  }

  return result
}

fn isValidAction(action: string): bool {
  let validActions = [] as [string]
  validActions = append(validActions, "analyze_delta")
  validActions = append(validActions, "generate_content")
  validActions = append(validActions, "generate_readme")
  validActions = append(validActions, "publish_social")
  validActions = append(validActions, "map_dependencies")
  validActions = append(validActions, "analyze_metrics")

  for validAction in validActions {
    if action == validAction {
      return true
    }
  }

  return false
}

fn serializeMessage(message: map): string {
  let result = "{"

  result = result + "\"id\":\"" + message["id"] + "\","
  result = result + "\"from\":\"" + message["from"] + "\","
  result = result + "\"to\":\"" + message["to"] + "\","
  result = result + "\"type\":\"" + message["type"] + "\","
  result = result + "\"action\":\"" + message["action"] + "\""

  result = result + "}"

  return result
}

fn signMessage(message: map, signingKey: string): map {
  let dataToSign = message["id"] + message["from"] + message["action"]
  let signature = simpleSignature(dataToSign, signingKey)
  message["signature"] = signature
  return message
}

fn verifyMessageSignature(message: map, signingKey: string): bool {
  let signature = message["signature"]
  let dataToSign = message["id"] + message["from"] + message["action"]
  let expectedSignature = simpleSignature(dataToSign, signingKey)
  return signature == expectedSignature
}

fn simpleSignature(data: string, key: string): string {
  let hash = 0 as i64
  let i = 0

  while i < len(data) {
    hash = (hash * 31 + 1) % 0x7FFFFFFFFFFFFFFF
    i = i + 1
  }

  return padToLength(toHexString(hash as i32), 40, "0")
}

fn routeAndProcessMessage(message: map): map {
  let action = message["action"]

  if !isValidAction(action) {
    message["status"] = "error"
    return message
  }

  message["status"] = "processed"
  return message
}

fn createTransaction(message: map): map {
  return {
    "transactionId": message["id"],
    "initiatedBy": message["from"],
    "target": message["to"],
    "action": message["action"],
    "startTime": 1710610800 as i64,
    "endTime": 0 as i64,
    "status": "pending",
    "responses": [] as [map]
  }
}

fn addResponseToTransaction(transaction: map, response: map): map {
  let responses = transaction["responses"]
  responses = append(responses, response)
  transaction["responses"] = responses
  transaction["status"] = "completed"
  return transaction
}

fn getAgentId(agentName: string): string {
  if agentName == "cmo" { return "agent:cmo:opus" }
  else if agentName == "content-writer" { return "agent:content-writer:sonnet" }
  else if agentName == "social-media" { return "agent:social-media:haiku" }
  else if agentName == "community-manager" { return "agent:community-manager:haiku" }
  else if agentName == "analytics" { return "agent:analytics:haiku" }
  else { return "agent:unknown" }
}

fn toHexString(num: i32): string {
  if num == 0 { return "0" }

  let hex = ""
  let hexChars = "0123456789abcdef"
  let n = num

  while n > 0 {
    let remainder = n % 16
    hex = getCharAtIndex(hexChars, remainder) + hex
    n = n / 16
  }

  return hex
}

fn padToLength(s: string, length: i32, padChar: string): string {
  let currentLen = len(s)
  let result = s

  let i = 0
  while i < (length - currentLen) {
    result = padChar + result
    i = i + 1
  }

  return result
}

fn getCharAtIndex(s: string, index: i32): string {
  if index < 0 || index >= len(s) {
    return ""
  }
  return substring(s, index, index + 1)
}

fn substring(s: string, start: i32, end: i32): string {
  let result = ""
  let i = start

  while i < end && i < len(s) {
    result = result + getCharAtIndex(s, i)
    i = i + 1
  }

  return result
}

fn intToString(num: i32): string {
  if num == 0 {
    return "0"
  }

  let result = ""
  let n = num
  let digits = "0123456789"

  while n > 0 {
    let digit = n % 10
    result = getCharAtIndex(digits, digit) + result
    n = n / 10
  }

  return result
}

fn boolToString(b: bool): string {
  if b {
    return "true"
  } else {
    return "false"
  }
}

